[tool error]
{
  "ok": false,
  "name": "create_alignment",
  "error": {
    "type": "invalid_params",
    "message": "2000 is not of type 'array' (at 'pis.1')",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1
        },
        "pis": {
          "type": "array",
          "items": {
            "type": "array",
            "items": {
              "type": "number"
            },
            "minItems": 2,
            "maxItems": 3,
            "description": "[x, y] or [x, y, radius]"
          },
          "minItems": 2
        },
        "elements": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "kind": {
                "enum": [
                  "tangent",
                  "curve"
                ]
              },
              "start": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "end": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "pc": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "pt": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "center": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "radius": {
                "type": "number",
                "exclusiveMinimum": 0
              },
              "direction": {
                "enum": [
                  "L",
                  "R"
                ]
              }
            },
            "required": [
              "kind"
            ],
            "additionalProperties": false
          },
          "minItems": 1
        },
        "start": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "BEGIN, where legs start: [x, y] = [easting, northing]"
        },
        "legs": {
          "type": "array",
          "items": {
            "type": [
              "object",
              "string"
            ],
            "description": "one tangent, from one PI to the next: a direction (exactly one of bearing, azimuth, deflection, angle_right) and the distance to the next PI; radius is the curve at the PI where this leg starts (a leg after the first). Or as text: \"S 76°15'00\\\" E 650\", \"33 L 820 R=450\"",
            "properties": {
              "bearing": {
                "type": "string",
                "description": "quadrant bearing: N 47°30'15\" E, S47-30-15W, N47E"
              },
              "azimuth": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "degrees clockwise from north, 0-360"
              },
              "deflection": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "the angle the alignment turns at the PI where this leg starts: '33 L', '18°30'00\" RT', or a number with right positive; or its size with turn"
              },
              "turn": {
                "type": "string",
                "enum": [
                  "left",
                  "right",
                  "L",
                  "R"
                ],
                "description": "which way a deflection turns"
              },
              "angle_right": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "angle clockwise from the backsight"
              },
              "distance": {
                "type": "number",
                "exclusiveMinimum": 0,
                "description": "feet from this leg's PI to the next PI"
              },
              "radius": {
                "type": "number",
                "minimum": 0,
                "description": "the curve at the PI where this leg starts (0 or omitted: none, which needs angle_points)"
              }
            },
            "additionalProperties": false
          },
          "minItems": 1,
          "description": "the layout as bearings and distances, PI to PI from start -- as a report describes it: 'S 76° E 650 ft to PI-2, where it deflects 33° left on a 450 ft curve; then 820 ft...' is [{bearing: 'S 76 E', distance: 650}, {deflection: '33 L', radius: 450, distance: 820}, ...]"
        },
        "begin_station": {
          "type": [
            "number",
            "string"
          ],
          "description": "display station: feet (8400) or '84+00.00'"
        },
        "equations": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "back": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "display station: feet (8400) or '84+00.00'"
              },
              "ahead": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "display station: feet (8400) or '84+00.00'"
              },
              "raw_station": {
                "type": "number"
              }
            },
            "required": [
              "back",
              "ahead"
            ],
            "additionalProperties": false
          }
        },
        "description": {
          "type": "string"
        },
        "angle_points": {
          "type": "boolean",
          "description": "allow interior PIs of radius 0: angle points, where the tangents meet with no curve -- a layout whose curves come later (default false: a missing radius is refused)"
        }
      },
      "required": [
        "name"
      ],
      "additionalProperties": false
    },
    "example": {
      "name": "ALIGN-1",
      "begin_station": "80+00",
      "pis": [
        [
          4100,
          7300
        ],
        [
          4914.359354,
          7300,
          800
        ],
        [
          5533.012702,
          7657.179677
        ]
      ]
    }
  },
  "warnings": []
}

[tool error]
{
  "ok": false,
  "name": "offset_entity",
  "error": {
    "type": "invalid_params",
    "message": "-14 is less than or equal to the minimum of 0 (at 'distance')",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "ids": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "minItems": 1,
          "description": "what to copy parallel: one line, polyline, arc or circle, or several that join end to end (in order along them), offset together as one path. Reference elements ('BASE:LN-017') may be copied into this document"
        },
        "distance": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "how far, with side or toward"
        },
        "side": {
          "type": "string",
          "enum": [
            "left",
            "right"
          ],
          "description": "left or right of the direction the path runs: a line start to end, a polyline in vertex order, an arc or circle counter-clockwise, a chain in the order of ids"
        },
        "toward": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "a point on the side to offset to, the way a drafter clicks the side"
        },
        "through": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "a point the parallel passes through; the distance is measured square to the path"
        },
        "offsets": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": [
              "number",
              "string"
            ]
          },
          "description": "several parallels at once, right of the path's direction positive ('15L', '15R' say the side): [-15, 15] is both edges of a 30 ft pavement"
        },
        "join": {
          "type": "string",
          "enum": [
            "sharp",
            "round"
          ],
          "description": "outside corners: sharp extends the pieces to meet (default), round swings an arc about the corner"
        },
        "connect_tolerance": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "largest gap between chained pieces (default 0.01)"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer of the copies; default the source's layer"
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ]
        }
      },
      "required": [
        "ids"
      ],
      "additionalProperties": false
    },
    "example": {
      "ids": [
        "LN-001"
      ],
      "distance": 15.0,
      "side": "right",
      "layer": "V-ROAD-EOP"
    }
  },
  "warnings": []
}
